:root {
  --ink: #000;
  --panel: #bdbdbd;
  --accent: #ffb000;
  --screen: #1a1a1a;
  --screen-text: #6eff6e;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #4a4a4a;
  font-family: 'Courier New', Courier, monospace;
}
.calc {
  width: min(92vw, 340px);
  padding: 22px;
  background: var(--panel);
  border: 4px solid var(--ink);
  box-shadow: 10px 10px 0 var(--ink);
}
h1 {
  margin: 0 0 18px;
  text-align: center;
  font-size: 1.3rem;
  letter-spacing: 2px;
  text-transform: uppercase;
}
.field {
  display: grid;
  gap: 6px;
  margin-bottom: 12px;
}
label {
  font-weight: bold;
  font-size: 0.85rem;
}
input, select, button {
  width: 100%;
  padding: 9px;
  border: 3px solid var(--ink);
  border-radius: 0;
  background: #fff;
  font: inherit;
  font-size: 1rem;
}
button {
  background: var(--accent);
  font-weight: bold;
  cursor: pointer;
  margin-top: 4px;
  box-shadow: 4px 4px 0 var(--ink);
}
button:active {
  box-shadow: 1px 1px 0 var(--ink);
  transform: translate(3px, 3px);
}
.result-field output {
  display: block;
  min-height: 1.6em;
  padding: 8px;
  background: var(--screen);
  color: var(--screen-text);
  border: 4px solid var(--ink);
  box-shadow: inset 0 0 0 2px #000;
  font-size: 1.5rem;
  text-align: right;
}
:focus-visible {
  outline: 3px dashed #fff;
  outline-offset: 2px;
}

'use strict';

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateButton = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function calculate() {
  const left = leftInput.value.trim();
  const right = rightInput.value.trim();

  if (left === '' || right === '') {
    resultOutput.textContent = 'Error';
    return;
  }

  const leftNumber = Number(left);
  const rightNumber = Number(right);

  if (!Number.isFinite(leftNumber) || !Number.isFinite(rightNumber)) {
    resultOutput.textContent = 'Error';
    return;
  }

  if (operationSelect.value === 'divide' && rightNumber === 0) {
    resultOutput.textContent = 'Error';
    return;
  }

  let value;
  switch (operationSelect.value) {
    case 'add':
      value = leftNumber + rightNumber;
      break;
    case 'subtract':
      value = leftNumber - rightNumber;
      break;
    case 'multiply':
      value = leftNumber * rightNumber;
      break;
    case 'divide':
      value = leftNumber / rightNumber;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  if (!Number.isFinite(value)) {
    resultOutput.textContent = 'Error';
    return;
  }

  resultOutput.textContent = String(value);
}

calculateButton.addEventListener('click', calculate);
